import fs from 'node:fs';
const root = new URL('.', import.meta.url);
const data = JSON.parse(fs.readFileSync(new URL('tasks.json', root), 'utf8'));
const lines = data.items.filter(x => x.status !== 'done').map(x => '- ' + x.title);
fs.writeFileSync(new URL('TODO.md', root), 'Generated from tasks.json; do not edit.\n' + lines.join('\n') + '\n');
